<?php namespace App\Http\Controllers;
use App\Models\{Entry,Source,Submission,ImportRun,Category}; use Illuminate\Http\Request; use Illuminate\Support\Facades\{Auth,DB}; use App\Services\AdminActivity; use Illuminate\Support\Str;
class AdminController {
 public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);if(Auth::attempt($v+['is_admin'=>true])){$r->session()->regenerate();return redirect('/admin');}return back()->withErrors(['email'=>'Invalid administrator credentials.']);}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/admin/login');}
 public function dashboard(){return view('admin.dashboard',['counts'=>['All entries'=>Entry::count(),'Pending review'=>Entry::where('status','pending')->count(),'Published'=>Entry::where('status','published')->count(),'Pending submissions'=>Submission::where('status','pending')->count(),'Enabled sources'=>Source::where('enabled',true)->count(),'Failed imports (7 days)'=>ImportRun::where('status','failed')->where('created_at','>=',now()->subDays(7))->count()],'types'=>Entry::selectRaw('type,count(*) as total')->groupBy('type')->pluck('total','type'),'runs'=>ImportRun::latest()->limit(8)->get()]);}
 public function content(Request $r,string $type){abort_unless($type==='all'||array_key_exists($type,config('obm.types')),404);$v=$r->validate(['q'=>'nullable|string|max:100','status'=>'nullable|in:pending,published,rejected','category'=>'nullable|string|max:100']);$q=Entry::query();if($type!=='all')$q->where('type',$type);if(!empty($v['q']))$q->where(fn($x)=>$x->where('title','like','%'.$v['q'].'%')->orWhere('title_bn','like','%'.$v['q'].'%'));foreach(['status','category'] as $f)if(!empty($v[$f]))$q->where($f,$v[$f]);return view('admin.content',['type'=>$type,'entries'=>$q->latest()->paginate(25)->withQueryString(),'categories'=>Category::orderBy('name')->get()]);}
 public function sources(){return view('admin.sources',['sources'=>Source::latest()->paginate(20)]);}
 public function submissions(){return view('admin.submissions',['submissions'=>Submission::latest()->paginate(20)]);}
 public function imports(){return view('admin.imports',['runs'=>ImportRun::latest()->paginate(30)]);}
 public function entry(Request $r,?Entry $entry=null){
  $v=$r->validate(['type'=>'required|in:job,scholarship,event,news,directory','title'=>'required|string|max:255','title_bn'=>'nullable|string|max:255','summary'=>'nullable|string|max:10000','country'=>'nullable|string|max:100','category'=>'nullable|string|max:100','category_text'=>'nullable|string|max:100','city'=>'nullable|string|max:100','url'=>'required|url:http,https|max:2048','status'=>'required|in:pending,published,rejected','deadline'=>'nullable|date','event_start'=>'nullable|date','expires_at'=>'nullable|date','address'=>'nullable|string|max:500','phone'=>'nullable|string|max:100','contact_email'=>'nullable|email:rfc|max:254','subcategory'=>'nullable|string|max:100']);
  if($v['status']==='published'){foreach(['deadline','event_start','expires_at'] as $date){if(!empty($v[$date])&&\Illuminate\Support\Carbon::parse($v[$date])->isPast())return back()->withInput()->withErrors([$date=>'Update expired dates before publishing.']);}}
  if($v['type']==='directory'&&!Category::where('name',$v['category']??'')->exists())return back()->withInput()->withErrors(['category'=>'Choose an existing directory category.']);
  if($v['type']!=='directory')$v['category']=$v['category_text']??null;
  unset($v['category_text']);$details=$entry?->details??[];foreach(['address','phone','contact_email','subcategory'] as $key){if($v['type']==='directory')$details[$key]=$v[$key]??null;unset($v[$key]);}$v['details']=$details;
  if($entry && ($entry->url!==$v['url'] || $entry->title!==$v['title'] || $entry->title_bn!==($v['title_bn']??null) || $entry->summary!==($v['summary']??null) || $entry->details!==$details || $entry->type!==$v['type'] || $entry->country!==($v['country']??null) || $entry->city!==($v['city']??null)))$v+=['verified_at'=>null];
  if($entry && $entry->url!==$v['url'])$v+=['link_checked_at'=>null,'link_status'=>null];
  DB::transaction(function()use($entry,$v){$previous=$entry?->status;if($entry)$entry->update($v);else $entry=Entry::create($v+['slug'=>Str::limit(Str::slug($v['title']),150,'').'-'.Str::lower(Str::random(10)),'fingerprint'=>hash('sha256',Str::uuid()->toString())]);AdminActivity::record('save','entry',$entry->id,['previous_status'=>$previous,'status'=>$entry->status]);});
  return redirect('/admin/content/'.$v['type'])->with('success','Entry saved');
 }
 public function status(Request $r,Entry $entry){$v=$r->validate(['status'=>'required|in:pending,published,rejected']);if($v['status']==='published'&&($entry->expires_at?->isPast()||$entry->deadline?->isPast()||$entry->event_start?->isPast()))return back()->withErrors(['status'=>'Update expired dates before publishing.']);DB::transaction(function()use($entry,$v){$old=$entry->status;$entry->update($v);AdminActivity::record('status','entry',$entry->id,['from'=>$old,'to'=>$entry->status]);});return back()->with('success','Publication status updated.');}
 public function activity(){return view('admin.activity',['activity'=>DB::table('admin_activity')->leftJoin('users','users.id','=','admin_activity.user_id')->select('admin_activity.*','users.name as administrator')->latest('admin_activity.id')->paginate(30)]);}
 public function source(Request $r,?Source $source=null){$v=$r->validate(['name'=>'required|string|max:150','driver'=>'required|in:rss,adzuna','type'=>'required|in:job,scholarship,event,news','url'=>'required|url:https|max:2048','country'=>'nullable|string|max:100','interval_minutes'=>'required|integer|min:60|max:10080','enabled'=>'nullable|boolean']);$v['enabled']=$r->boolean('enabled');if($v['driver']==='adzuna'&&($v['type']!=='job'||!preg_match('/^[a-z]{2}$/D',$v['country']??'')))return back()->withErrors(['country'=>'Adzuna requires job type and two-letter country code.']);DB::transaction(function()use($source,$v){if($source)$source->update($v);else $source=Source::create($v);AdminActivity::record('save','source',$source->id,['enabled'=>$source->enabled]);});return back()->with('success','Source saved');}
 public function verify(Entry $entry){abort_unless($entry->type==='directory',404);DB::transaction(function()use($entry){$entry->update(['verified_at'=>now()]);AdminActivity::record('verify','entry',$entry->id);});return back()->with('success','Editorial review recorded');}
 public function submission(Request $r,Submission $submission){ $v=$r->validate(['status'=>'required|in:pending,reviewed,rejected']);DB::transaction(function()use($submission,$v){$old=$submission->status;$submission->update($v);AdminActivity::record('review','submission',$submission->id,['from'=>$old,'to'=>$submission->status]);});return back()->with('success','Submission review saved. No public entry was automatically created.');}
}
